select id, name, trade_names, atc_code, amount_unit, dose_units, max_single_dose_amount, unit_equivalence, route_alternatives, cautions, monitoring, preparation, interactions, review_rules, dosing_weight, dose_rounding_step, notes, sort_order, sources, availability
from jsonb_populate_recordset(null::public.drugs, $catalog$[{"id":"mosunetuzumab","name":{"uk":"Мозунетузумаб","en":"Mosunetuzumab"},"trade_names":["Lunsumio","Lunsumio Velo"],"atc_code":"L01FX25","amount_unit":"mg","dose_units":[],"max_single_dose_amount":null,"unit_equivalence":null,"route_alternatives":null,"cautions":null,"monitoring":null,"preparation":[{"routes":["iv_infusion"],"notes":{"uk":"З мішка 0,9% або 0,45% натрію хлориду відбирають об'єм, що дорівнює потрібному об'єму препарату, і виливають; потім уводять препарат. Пакети — лише з ПВХ або поліолефіну (поліетилен, поліпропілен). Перемішують повільним перевертанням, не струшують. Залишок у флаконі викидають. Готовий розчин уводять одразу; за потреби зберігають до 24 год при 2–8 °C і до 16 год при 9–30 °C, перед уведенням дають зігрітися до кімнатної температури.","en":"Withdraw from a 0.9% or 0.45% sodium chloride bag a volume equal to the volume of the drug needed and discard it, then add the drug. Use only PVC or polyolefin (polyethylene, polypropylene) bags. Mix by slow inversion, do not shake. Discard what is left in the vial. Give the prepared solution at once; if needed it keeps for up to 24 hours at 2-8 °C and up to 16 hours at 9-30 °C, and is allowed to reach room temperature before administration."},"source":{"name":"FDA label: LUNSUMIO (mosunetuzumab-axgb), Dosage and Administration 2.5","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2ef0cf38-101c-4681-98fe-c05dc9ead443","version":"SPL на DailyMed","checkedOn":"2026-11-20"}}],"interactions":null,"review_rules":null,"dosing_weight":"actual","dose_rounding_step":null,"notes":null,"sort_order":0,"sources":[{"name":"FDA label: LUNSUMIO (mosunetuzumab-axgb) concentrate — флакони 1 мг/мл і 30 мг/30 мл, розведення в 0,9% або 0,45% NaCl","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2ef0cf38-101c-4681-98fe-c05dc9ead443","version":"SPL на DailyMed","checkedOn":"2026-11-20"},{"name":"FDA label: LUNSUMIO VELO (mosunetuzumab-axgb) injection — підшкірні флакони 5 мг/0,5 мл і 45 мг/мл","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6a2b6dc2-48bd-4da7-a611-bc6bae2893c8","version":"SPL на DailyMed","checkedOn":"2026-11-20"},{"name":"Державний реєстр лікарських засобів України (пошук на drlz.com.ua)","url":"https://www.drlz.com.ua/poshuk?q=%D0%BC%D0%BE%D0%B7%D1%83%D0%BD%D0%B5%D1%82%D1%83%D0%B7%D1%83%D0%BC%D0%B0%D0%B1","version":"пошук 20.11.2026: збігів немає","checkedOn":"2026-11-20"}],"availability":"unavailable"},{"id":"sonrotoclax","name":{"uk":"Сонротоклакс","en":"Sonrotoclax"},"trade_names":["Beqalzi"],"atc_code":null,"amount_unit":"mg","dose_units":[],"max_single_dose_amount":null,"unit_equivalence":null,"route_alternatives":null,"cautions":null,"monitoring":null,"preparation":null,"interactions":null,"review_rules":null,"dosing_weight":"actual","dose_rounding_step":null,"notes":{"uk":"Інгібітор BCL-2. Нарощування дози за інструкцією: 1-й тиждень 1 мг (дні 1–3) і 2 мг (дні 4–7), 2-й — 5 і 10 мг, 3-й — 20 і 40 мг, 4-й — 80 і 160 мг; з 5-го тижня 320 мг раз на добу до прогресування чи непереносимості. Ризик синдрому лізису пухлини найбільший під час нарощування і при поновленні після перерви понад 7 днів. Сильні інгібітори CYP3A протипоказані на початку й під час нарощування.","en":"A BCL-2 inhibitor. The label's ramp-up: week 1, 1 mg (days 1-3) and 2 mg (days 4-7); week 2, 5 and 10 mg; week 3, 20 and 40 mg; week 4, 80 and 160 mg; from week 5, 320 mg once daily until progression or intolerance. The risk of tumour lysis syndrome is highest during the ramp-up and on restarting after a break of more than seven days. Strong CYP3A inhibitors are contraindicated at initiation and during the ramp-up."},"sort_order":0,"sources":[{"name":"FDA label: BEQALZI (sonrotoclax) — таблетки 1, 5, 20 і 80 мг; 4-тижневе нарощування дози, цільова доза 320 мг раз на добу при рецидивній/рефрактерній мантійноклітинній лімфомі після ≥2 ліній, включно з інгібітором BTK","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ff684558-e9cb-46de-a8bf-f4d79093df7a","version":"SPL на DailyMed","checkedOn":"2026-11-20"},{"name":"Державний реєстр лікарських засобів України (пошук на drlz.com.ua)","url":"https://www.drlz.com.ua/poshuk?q=%D1%81%D0%BE%D0%BD%D1%80%D0%BE%D1%82%D0%BE%D0%BA%D0%BB%D0%B0%D0%BA%D1%81","version":"пошук 20.11.2026: збігів немає","checkedOn":"2026-11-20"}],"availability":"unavailable"},{"id":"temsirolimus","name":{"uk":"Темсиролімус","en":"Temsirolimus"},"trade_names":["Torisel"],"atc_code":"L01EG01","amount_unit":"mg","dose_units":[],"max_single_dose_amount":null,"unit_equivalence":null,"route_alternatives":null,"cautions":null,"monitoring":null,"preparation":[{"routes":["iv_infusion"],"notes":{"uk":"Розведення двоетапне: 1) у флакон вносять 1,8 мл доданого розчинника — виходить 10 мг/мл; 2) потрібний об'єм (2,5 мл на дозу 25 мг) вносять у 250 мл 0,9% натрію хлориду. Перемішують перевертанням, без струшування: утворюється піна. Готовий розчин берегти від яскравого світла й увести протягом 6 годин від моменту додавання в натрію хлорид. Через вимивання DEHP готовий розчин зберігають у скляних чи поліпропіленових пляшках або поліпропіленових/поліолефінових пакетах і вводять системою без ПВХ і DEHP; рекомендований вбудований поліетерсульфоновий фільтр із порами не більш як 5 мкм (одночасно вбудований і кінцевий фільтр не застосовують). За 30 хв до введення — H1-антигістамінний препарат (дифенгідрамін 25–50 мг в/в або подібний).","en":"A two-step dilution: 1) add the 1.8 mL of supplied diluent to the vial, giving 10 mg/mL; 2) add the required volume (2.5 mL for a 25 mg dose) to 250 mL of 0.9% sodium chloride. Mix by inversion, without shaking, which causes foam. Protect the prepared solution from bright light and give it within six hours of adding it to the sodium chloride. Because of DEHP leaching, keep the final solution in glass or polypropylene bottles or polypropylene/polyolefin bags and give it through a non-PVC, non-DEHP set; an in-line polyethersulfone filter of no more than 5 microns is recommended (not together with an end filter). An H1 antihistamine (diphenhydramine 25-50 mg IV or similar) is given 30 minutes beforehand."},"source":{"name":"FDA label: TORISEL (temsirolimus), Dosage and Administration 2.2, 2.5, 2.6","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=95b7dc92-2180-42f1-8699-3c28f609e674","version":"SPL на DailyMed","checkedOn":"2026-11-20"}}],"interactions":null,"review_rules":null,"dosing_weight":"actual","dose_rounding_step":null,"notes":null,"sort_order":0,"sources":[{"name":"FDA label: TORISEL (temsirolimus) — набір: флакон 25 мг/мл і флакон розчинника 1,8 мл; двоетапне розведення, 250 мл 0,9% NaCl, інфузія 30–60 хв щотижня","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=95b7dc92-2180-42f1-8699-3c28f609e674","version":"SPL на DailyMed","checkedOn":"2026-11-20"},{"name":"Державний реєстр лікарських засобів України (пошук на drlz.com.ua)","url":"https://www.drlz.com.ua/poshuk?q=%D1%82%D0%B5%D0%BC%D1%81%D0%B8%D1%80%D0%BE%D0%BB%D1%96%D0%BC%D1%83%D1%81","version":"пошук 20.11.2026: точних збігів немає","checkedOn":"2026-11-20"}],"availability":"unavailable"}]$catalog$::jsonb)
