from jsonb_populate_recordset(null::public.drug_infusion_params, $catalog$[{"id":"mosunetuzumab.nacl","drug_id":"mosunetuzumab","solvent":"sodium_chloride_0_9","concentration_min_mg_ml":null,"concentration_max_mg_ml":null,"stock_concentration_mg_ml":1,"max_rate_mg_min":null,"duration_options":[],"min_duration_min":null,"rate_ramp":null,"ramp_sequence":null,"bag_volumes_ml":[50,100,250],"duration_min":null,"is_default":true,"notes":{"uk":"Концентрат 1 мг/мл. Інструкція задає не межі концентрації, а розмір мішка за дозою: 1 і 2 мг — 50 або 100 мл; 30 мг — 50, 100 або 250 мл; 60 мг — 100 або 250 мл. Розчинник — 0,9% або 0,45% натрію хлорид. Тривалість інфузії задає схема: у 1-му циклі не менш як 4 год, далі 2 год, якщо 1-й цикл перенесено добре.","en":"The concentrate is 1 mg/mL. The label sets the bag size by the dose rather than concentration limits: 1 and 2 mg into 50 or 100 mL; 30 mg into 50, 100 or 250 mL; 60 mg into 100 or 250 mL. The diluent is 0.9% or 0.45% sodium chloride. The regimen sets the duration: at least 4 hours in cycle 1, then 2 hours if cycle 1 was well tolerated."},"sources":[{"name":"FDA label: LUNSUMIO (mosunetuzumab-axgb), Dosage and Administration 2.5, табл. 7","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2ef0cf38-101c-4681-98fe-c05dc9ead443","version":"SPL на DailyMed","checkedOn":"2026-11-20"}],"sort_order":0},{"id":"temsirolimus.nacl","drug_id":"temsirolimus","solvent":"sodium_chloride_0_9","concentration_min_mg_ml":null,"concentration_max_mg_ml":null,"stock_concentration_mg_ml":10,"max_rate_mg_min":null,"duration_options":[],"min_duration_min":null,"rate_ramp":null,"ramp_sequence":null,"bag_volumes_ml":[250],"duration_min":null,"is_default":true,"notes":{"uk":"Після змішування з доданим розчинником у флаконі виходить 30 мг/3 мл, тобто 10 мг/мл; далі потрібний об'єм вносять у 250 мл 0,9% NaCl. Меж концентрації в готовому розчині інструкція не дає, тому об'єм мішка фіксований — 250 мл. Тривалість інфузії — 30–60 хв (у схемі).","en":"Mixing with the supplied diluent gives 30 mg/3 mL in the vial, that is 10 mg/mL; the required volume then goes into 250 mL of 0.9% NaCl. The label gives no concentration limits for the final solution, so the bag volume is fixed at 250 mL. The infusion lasts 30-60 minutes (set by the regimen)."},"sources":[{"name":"FDA label: TORISEL (temsirolimus), Dosage and Administration 2.5–2.6","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=95b7dc92-2180-42f1-8699-3c28f609e674","version":"SPL на DailyMed","checkedOn":"2026-11-20"}],"sort_order":0}]$catalog$::jsonb)
