insert into public.regimens (id, short_name, name, description, cycle_length_days, default_cycles, sort_order, sources, evidence, reference, course, print_forms)
select id, short_name, name, description, cycle_length_days, default_cycles, sort_order, sources, evidence, reference, course, print_forms
from jsonb_populate_recordset(null::public.regimens, $catalog$[{"id":"ref-fl-mosunetuzumab","short_name":"Мозунетузумаб / одронекстамаб","name":{"uk":"Бісспецифічні антитіла CD20×CD3: мозунетузумаб, одронекстамаб (ФЛ)","en":"CD20×CD3 bispecific antibodies: mosunetuzumab, odronextamab (FL)"},"description":null,"cycle_length_days":null,"default_cycles":null,"sort_order":0,"sources":[{"name":"UpToDate: Treatment of relapsed or refractory follicular lymphoma","url":"https://www.uptodate.com/contents/treatment-of-relapsed-or-refractory-follicular-lymphoma","version":"тема оновлена 03.08.2026","checkedOn":"2026-10-04"}],"evidence":null,"reference":{"summary":{"uk":"Множинний рецидив ФЛ, особливо з короткою попередньою ремісією (<24 міс.): відповідь приблизно у 80%, близько половини живі без прогресування через 2 роки.","en":"Multiply relapsed FL, especially with a short prior remission (<24 months): response in about 80%, about half alive and progression-free at two years."},"drugs":[{"name":{"uk":"Мозунетузумаб","en":"Mosunetuzumab"},"drug_id":"mosunetuzumab"},{"name":{"uk":"Одронекстамаб","en":"Odronextamab"}},{"name":{"uk":"Епкоритамаб","en":"Epcoritamab"},"drug_id":"epcoritamab"}],"key_info":[{"uk":"Мозунетузумаб — 8–17 циклів залежно від відповіді; епкоритамаб і одронекстамаб — до прогресування. Починають із сходинок дози, далі інтервал 2–4 тижні.","en":"Mosunetuzumab for 8 to 17 cycles depending on response; epcoritamab and odronextamab until progression. Treatment begins with step-up doses, then an interval of 2 to 4 weeks."},{"uk":"СВЦ у 44–66% (переважно 1–2 ступеня, у першому циклі); профілактика пневмоцистної, герпетичної та VZV-інфекції; ризик реактивації гепатиту B.","en":"Cytokine release in 44 to 66% (mostly grade 1 or 2, in the first cycle); prophylaxis against Pneumocystis, herpes simplex and VZV; risk of hepatitis B reactivation."}],"gap":{"uk":"UpToDate не наводить сходинок доз мозунетузумабу й одронекстамабу; одронекстамаба в довіднику ще немає.","en":"UpToDate gives no step-up doses for mosunetuzumab and odronextamab; odronextamab is not in the catalog yet."},"availability":"unavailable"},"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"ref-mcl-sonrotoclax","short_name":"Сонротоклакс","name":{"uk":"Сонротоклакс при мантійноклітинній лімфомі","en":"Sonrotoclax in mantle cell lymphoma"},"description":null,"cycle_length_days":null,"default_cycles":null,"sort_order":0,"sources":[{"name":"UpToDate: Treatment of relapsed or refractory mantle cell lymphoma","url":"https://www.uptodate.com/contents/treatment-of-relapsed-or-refractory-mantle-cell-lymphoma","version":"перевірено 2026-10-04","checkedOn":"2026-10-04"},{"name":"FDA label: BEQALZI (sonrotoclax) — показання, нарощування дози й цільова доза 320 мг","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ff684558-e9cb-46de-a8bf-f4d79093df7a","version":"SPL на DailyMed","checkedOn":"2026-11-20"}],"evidence":null,"reference":{"summary":{"uk":"Другий BCL2-інгібітор; схвалений FDA після ≥2 ліній, включно з інгібітором BTK: відповідь 52% (повна 15%), медіана відповіді 16 місяців, ВБП 7 місяців (125 хворих).","en":"A second-generation BCL2 inhibitor; approved by the FDA after at least two lines including a BTK inhibitor: response 52% (complete 15%), median duration of response 16 months, PFS 7 months (125 patients)."},"drugs":[{"name":{"uk":"Сонротоклакс","en":"Sonrotoclax"},"drug_id":"sonrotoclax"}],"key_info":[{"uk":"Інструкція FDA: нарощування дози 4 тижні (1 і 2 мг, 5 і 10 мг, 20 і 40 мг, 80 і 160 мг — по 3 і 4 дні), з 5-го тижня 320 мг раз на добу до прогресування чи непереносимості.","en":"The FDA label: a four-week ramp-up (1 and 2 mg, 5 and 10 mg, 20 and 40 mg, 80 and 160 mg, three days then four), and from week 5, 320 mg once daily until progression or intolerance."},{"uk":"Цитопенії, пневмонія (10%), синдром лізису пухлини (2%).","en":"Cytopenias, pneumonia (10%), tumor lysis syndrome (2%)."}],"gap":{"uk":"UpToDate дози не наводить. Нарощування й цільову дозу взято з інструкції FDA — вони в картці препарату; курс тут не розраховується, бо препарат приймають усередину щодня до прогресування.","en":"UpToDate gives no dose. The ramp-up and the target dose come from the FDA label and are in the drug card; no course is calculated here, because the drug is taken by mouth daily until progression."},"availability":"unavailable"},"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"ref-mcl-temsirolimus","short_name":"Темсиролімус","name":{"uk":"Темсиролімус при мантійноклітинній лімфомі","en":"Temsirolimus in mantle cell lymphoma"},"description":null,"cycle_length_days":null,"default_cycles":null,"sort_order":0,"sources":[{"name":"UpToDate: Treatment of relapsed or refractory mantle cell lymphoma","url":"https://www.uptodate.com/contents/treatment-of-relapsed-or-refractory-mantle-cell-lymphoma","version":"перевірено 2026-10-04","checkedOn":"2026-10-04"}],"evidence":null,"reference":{"summary":{"uk":"Схвалений EMA при рецидивній МКЛ: 175 мг щотижня 3 тижні, далі 75 або 25 мг щотижня. ВБП і відповідь кращі, ніж у вибору лікаря, але значні цитопенії й астенія; гірше за ібрутиніб.","en":"Approved by the EMA in relapsed MCL: 175 mg weekly for three weeks, then 75 or 25 mg weekly. Better PFS and response than investigator's choice, but substantial cytopenias and asthenia; worse than ibrutinib."},"drugs":[{"name":{"uk":"Темсиролімус","en":"Temsirolimus"},"drug_id":"temsirolimus"}],"key_info":[],"gap":{"uk":"В Україні препарат не зареєстрований (пошук у Державному реєстрі 20.11.2026). Фасовка, двоетапне розведення й премедикація антигістамінним — у картці препарату; курс тут не розраховується.","en":"The drug is not registered in Ukraine (state register search of 20 November 2026). The presentation, the two-step dilution and the antihistamine premedication are in the drug card; no course is calculated here."},"availability":"unavailable"},"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"ref-mosun-pola","short_name":"Мозунетузумаб + полатузумаб","name":{"uk":"Мозунетузумаб + полатузумаб ведотин (ДВКЛ, МКЛ)","en":"Mosunetuzumab + polatuzumab vedotin (DLBCL, MCL)"},"description":null,"cycle_length_days":null,"default_cycles":null,"sort_order":0,"sources":[{"name":"NCCN Guidelines: B-Cell Lymphomas","url":"https://www.nccn.org/guidelines/guidelines-detail?category=1&id=1480","version":"4.2026 від 20.05.2026","checkedOn":"2026-10-22"}],"evidence":null,"reference":{"summary":{"uk":"Рецидивна ДВКЛ у кандидатів, яким CAR-T не підходить: бажаний варіант NCCN (рецидив <12 міс. і >12 міс. без наміру на трансплантацію). Мантійноклітинна лімфома після інгібітора BTK — T-клітинна терапія в 2-й лінії. Мозунетузумаб може бути в/в або п/ш (різні інструкції введення).","en":"Relapsed DLBCL in patients not suited to CAR-T: a preferred NCCN option (relapse under 12 months, and over 12 months with no intention to transplant). Mantle cell lymphoma after a BTK inhibitor — T-cell therapy in the second line. Mosunetuzumab can be given IV or SC (different administration instructions)."},"drugs":[{"name":{"uk":"Мозунетузумаб","en":"Mosunetuzumab"},"drug_id":"mosunetuzumab"},{"name":{"uk":"Полатузумаб ведотин","en":"Polatuzumab vedotin"},"drug_id":"polatuzumab-vedotin"}],"key_info":[{"uk":"Біспецифічні антитіла CD20×CD3 мало ефективні при CD20-негативній пухлині — повторна біопсія для підтвердження антигена.","en":"CD20xCD3 bispecifics work poorly in CD20-negative disease — rebiopsy to confirm the antigen."},{"uk":"При МКЛ біспецифічні антитіла дають частіший синдром вивільнення цитокінів, ніж при ДВКЛ.","en":"In MCL bispecifics cause cytokine release syndrome more often than in DLBCL."}],"gap":{"uk":"NCCN дози не наводить; схема описана лише для ознайомлення.","en":"NCCN gives no doses; the regimen is described for reference only."},"availability":"unavailable"},"course":null,"print_forms":{"version":1,"forms":[]}}]$catalog$::jsonb)
on conflict (id) do update set short_name = excluded.short_name, name = excluded.name, description = excluded.description, cycle_length_days = excluded.cycle_length_days, default_cycles = excluded.default_cycles, sort_order = excluded.sort_order, sources = excluded.sources, evidence = excluded.evidence, reference = excluded.reference, course = excluded.course, print_forms = excluded.print_forms;

insert into public.diseases (id, name, summary, sort_order, clinical_group, references_json)
select id, name, summary, sort_order, clinical_group, references_json
from jsonb_populate_recordset(null::public.diseases, $catalog$[{"id":"aml","name":{"uk":"Гострий мієлоїдний лейкоз","en":"Acute myeloid leukaemia"},"summary":{"uk":"Клональна проліферація мієлоїдних бластів; потребує невідкладного обстеження й лікування.","en":"Clonal proliferation of myeloid blasts; needs urgent work-up and treatment."},"sort_order":0,"clinical_group":"acute-leukemia","references_json":[{"kind":"nccn","url":"https://www.nccn.org/guidelines/guidelines-detail?category=1&id=1411","label":null,"version":"5.2026","updated":"2026-07-15"},{"kind":"uptodate","url":"https://www.uptodate.com/contents/search?search=Acute%20myeloid%20leukaemia","label":null,"version":null,"updated":null},{"kind":"eviq","url":"https://www.eviq.org.au/search#/?query=Acute%20myeloid%20leukaemia","label":null,"version":null,"updated":null}]},{"id":"mantle-cell-lymphoma","name":{"uk":"Лімфома з клітин мантійної зони","en":"Mantle cell lymphoma"},"summary":{"uk":"В-клітинна лімфома з t(11;14) і циклін D1; перебіг здебільшого агресивний.","en":"B-cell lymphoma with t(11;14) and cyclin D1; usually an aggressive course."},"sort_order":0,"clinical_group":"lymphoma","references_json":[{"kind":"nccn","url":"https://www.nccn.org/guidelines/guidelines-detail?category=1&id=1480","label":null,"version":"4.2026","updated":"2026-05-20"},{"kind":"uptodate","url":"https://www.uptodate.com/contents/search?search=Mantle%20cell%20lymphoma","label":null,"version":null,"updated":null},{"kind":"eviq","url":"https://www.eviq.org.au/search#/?query=Mantle%20cell%20lymphoma","label":null,"version":null,"updated":null},{"kind":"other","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12541557/","label":{"uk":"EHA-EU MCL network: настанова з діагностики й лікування мантійноклітинної лімфоми","en":"EHA-EU MCL network guidelines for diagnosis and treatment of mantle cell lymphoma"},"version":"HemaSphere 2025;9(10):e70233","updated":"2025-10-22"},{"kind":"other","url":"https://doi.org/10.1093/annonc/mdx223","label":{"uk":"ESMO: мантійноклітинна лімфома, клінічна настанова (MIPI і MIPI-c, табл. 3)","en":"ESMO Clinical Practice Guidelines: mantle cell lymphoma (MIPI and MIPI-c, Table 3)"},"version":"Ann Oncol 2017;28(Suppl 4):iv62-71","updated":"2017-08-01"},{"kind":"other","url":"https://www.esmo.org/guidelines/living-guidelines/esmo-living-guideline-lymphomas","label":{"uk":"ESMO Living Guideline: лімфоми","en":"ESMO Living Guideline: Lymphomas"},"version":"v1.1","updated":"2026-02-01"}]}]$catalog$::jsonb)
on conflict (id) do update set name = excluded.name, summary = excluded.summary, sort_order = excluded.sort_order, clinical_group = excluded.clinical_group, references_json = excluded.references_json;

insert into public.treatment_nodes (id, disease_id, parent_id, kind, title, description, sort_order, steps)
select id, disease_id, parent_id, kind, title, description, sort_order, steps
from jsonb_populate_recordset(null::public.treatment_nodes, $catalog$[{"id":"aml.induction","disease_id":"aml","parent_id":null,"kind":"line","title":{"uk":"Індукція","en":"Induction"},"description":{"uk":"Інтенсивна індукція для пацієнтів, придатних до неї. Другий курс дають за відновленням показників, а не за календарем; кістковомозкову пункцію роблять після відновлення, перед другим курсом.","en":"Intensive induction for patients fit for it. The second course follows count recovery rather than the calendar; the marrow is sampled after recovery, before that course."},"sort_order":1,"steps":[]},{"id":"aml.consolidation","disease_id":"aml","parent_id":null,"kind":"line","title":{"uk":"Консолідація","en":"Consolidation"},"description":{"uk":"Після досягнення ремісії; вибір залежить від групи ризику й придатності до трансплантації.","en":"After remission is achieved; the choice depends on the risk group and transplant eligibility."},"sort_order":2,"steps":[]},{"id":"aml.salvage","disease_id":"aml","parent_id":null,"kind":"line","title":{"uk":"Рефрактерність і рецидив","en":"Refractory disease and relapse"},"description":{"uk":"Максимум два курси. Ідарубіцин у другому курсі зважують окремо через кумулятивну дозу антрацикліну.","en":"Two courses at most. The idarubicin of the second course is weighed separately because of the cumulative anthracycline dose."},"sort_order":3,"steps":[]},{"id":"mantle-cell-lymphoma.first-line-fit","disease_id":"mantle-cell-lymphoma","parent_id":null,"kind":"line","title":{"uk":"Перша лінія, молодші й збережені пацієнти","en":"First line, younger and fit patients"},"description":{"uk":"Більшість досліджень включала хворих до 65 років, але придатним пацієнтам і старшого віку (до 70 — за рішенням лікаря) радять ту саму тактику. Стандарт — індукція з ковалентним інгібітором BTK: R-CHOP з ібрутинібом у чергуванні з R-DHAP або R-DHAOx, далі 2 роки ібрутинібу і 3 роки підтримки ритуксимабом [I, A]. Якщо інгібітора BTK у першій лінії дістати не можна — індукція з ритуксимабом і високими дозами цитарабіну з консолідацією аутотрансплантацією і 3 роками підтримки ритуксимабом [I, B]: у довіднику це чергування Nordic MCL2 (R-maxi-CHOP / R-Ara-C). Аутотрансплантацію обговорюють окремо, якщо є чинники високого ризику [II, C]; при повній відповіді з невизначальною МЗХ за NGS-методом її можна не робити [II, A]. Хворого, не придатного до інтенсивних схем, лікують за рекомендаціями для літніх [II, A]. Джерело: EHA-EU MCL network guidelines, HemaSphere 2025;9(10):e70233, розділ «Younger patients»; NCCN B-Cell Lymphomas 4.2026 (MANT-4).","en":"Most trials enrolled patients up to 65 years, but fit older patients (up to 70 at the physician's discretion) are advised the same approach. The standard is induction containing a covalent BTK inhibitor: R-CHOP with ibrutinib alternating with R-DHAP or R-DHAOx, then two years of ibrutinib and three years of rituximab maintenance [I, A]. Where a covalent BTK inhibitor cannot be obtained first line: rituximab and high-dose cytarabine induction with autologous transplant consolidation and three years of rituximab maintenance [I, B] — in the catalog that is the Nordic MCL2 alternation (R-maxi-CHOP / R-Ara-C). Transplant is discussed separately when high-risk features are present [II, C]; in complete response with undetectable MRD by the NGS assay it can be omitted [II, A]. A patient unsuitable for dose-intense regimens is treated by the recommendations for older patients [II, A]. Source: EHA-EU MCL network guidelines, HemaSphere 2025;9(10):e70233, the Younger patients section; NCCN B-Cell Lymphomas 4.2026 (MANT-4)."},"sort_order":1,"steps":[]},{"id":"mantle-cell-lymphoma.first-line-elderly","disease_id":"mantle-cell-lymphoma","parent_id":null,"kind":"line","title":{"uk":"Перша лінія, пацієнти похилого віку","en":"First line, elderly patients"},"description":{"uk":"Хворим від 65–70 років, не придатним до інтенсивної терапії, і молодшим із супутніми хворобами пропонують на вибір: імунохіміотерапію з ритуксимабом — BR, VR-CAP або R-CHOP [I, B], R-BAC [III, B]; BR з акалабрутинібом [I, B]; безперервний ковалентний інгібітор BTK з ритуксимабом і 2 роками підтримки ритуксимабом (не схвалено ні EMA, ні FDA) [I, B]. Підтримку ритуксимабом дають не менш як 2 роки після BR [II, B], VR-CAP [IV, B] і R-CHOP [I, C]. VR-CAP не пригнічує Т-клітини, тому його обирають, коли далі можлива CAR-T або біспецифічні антитіла. Джерело: EHA-EU MCL network guidelines, HemaSphere 2025;9(10):e70233, розділ «Older and frail patients»; NCCN B-Cell Lymphomas 4.2026 (MANT-5).","en":"Patients of 65-70 years and over who are unsuitable for intensive therapy, and younger patients with comorbidities, are offered a choice: rituximab immunochemotherapy - BR, VR-CAP or R-CHOP [I, B], R-BAC [III, B]; BR with acalabrutinib [I, B]; a continuous covalent BTK inhibitor with rituximab and two years of rituximab maintenance (approved by neither the EMA nor the FDA) [I, B]. Rituximab maintenance is given for at least two years after BR [II, B], VR-CAP [IV, B] and R-CHOP [I, C]. VR-CAP spares T cells, so it is chosen when CAR-T or bispecific antibodies may follow. Source: EHA-EU MCL network guidelines, HemaSphere 2025;9(10):e70233, the Older and frail patients section; NCCN B-Cell Lymphomas 4.2026 (MANT-5)."},"sort_order":2,"steps":[]},{"id":"mantle-cell-lymphoma.relapsed","disease_id":"mantle-cell-lymphoma","parent_id":null,"kind":"line","title":{"uk":"Рецидив і рефрактерна хвороба","en":"Relapsed and refractory disease"},"description":{"uk":"Вибір залежить від того, чи був ковалентний інгібітор BTK і коли настав рецидив. Після імунохіміотерапії без нього, а також при пізньому рецидиві (понад 24 місяці після схеми з ковалентним BTKi), стандарт другої лінії — ковалентний інгібітор BTK (ібрутиніб, акалабрутиніб, занубрутиніб), сам або з венетоклаксом; при прогресії на ньому чи ранньому рецидиві (менш як 24 місяці) — нековалентний піртобрутиніб, CAR-T або біспецифічні антитіла. Враховують також ранню прогресію, бластоїдну морфологію, високий Ki-67 і стан TP53. Препарати в довіднику є, схем як таких немає: дозування постійне, усередину, до прогресування або непереносимості. Джерела: NCCN B-Cell Lymphomas 4.2026 (MANT-6A, MANT-6B); EHA-EU MCL network guidelines, HemaSphere 2025;9(10):e70233.","en":"The choice depends on whether a covalent BTK inhibitor was given and when the relapse came. After immunochemotherapy without one, and in late relapse (more than 24 months after a covalent-BTKi regimen), the second-line standard is a covalent BTK inhibitor (ibrutinib, acalabrutinib, zanubrutinib) alone or with venetoclax; on progression during one, or in early relapse (under 24 months), it is non-covalent pirtobrutinib, CAR-T or bispecific antibodies. Early progression, blastoid morphology, a high Ki-67 and TP53 status are weighed as well. The drugs are in the catalog but not as regimens: they are taken orally and continuously until progression or toxicity. Sources: NCCN B-Cell Lymphomas 4.2026 (MANT-6A, MANT-6B); EHA-EU MCL network guidelines, HemaSphere 2025;9(10):e70233."},"sort_order":3,"steps":[]}]$catalog$::jsonb)
on conflict (id) do update set disease_id = excluded.disease_id, parent_id = excluded.parent_id, kind = excluded.kind, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, steps = excluded.steps;

commit;
